
import { TOPOLOGY_PAGE_PROFILES } from "../config/topologyPageProfiles";
import { createPresentationTopology } from "../framework/topologyLayouts.ts";
import type { CollectionEntry } from "astro:content";

export interface OrganizationSceneNode {
  id: string;
  label: string;
  subtitle?: string;
  q: number;
  r: number;
  variant: string;
  size: string;
  active: boolean;
  selected: boolean;
  disabled?: boolean;
}

export interface OrganizationSceneEdge {
  from: string;
  to: string;
  kind: string;
  active: boolean;
  muted: boolean;
}

type OrganizationEntry = CollectionEntry<"organizations">;
type PeopleEntry = CollectionEntry<"people">;

interface OrganizationSceneTopologyInput {
  organization: OrganizationEntry;
  relatedPeople: PeopleEntry[];
}

interface ScenePosition {
  q: number;
  r: number;
}

const clusterOffsets: ScenePosition[] = [
  { q: 0, r: -2 },
  { q: 2, r: -2 },
  { q: 2, r: 0 },
  { q: 0, r: 2 },
  { q: -2, r: 2 },
  { q: -2, r: 0 },
];

function placeClusterNodes<T extends OrganizationSceneNode>(nodes: T[], anchor: ScenePosition, scale = 1): T[] {
  return nodes.map((node, index) => {
    const offset = clusterOffsets[index % clusterOffsets.length];
    const shell = Math.floor(index / clusterOffsets.length);
    const factor = scale + shell * 2;

    return {
      ...node,
      q: anchor.q + offset.q * factor,
      r: anchor.r + offset.r * factor,
    };
  });
}

export function createOrganizationSceneTopology({ organization, relatedPeople }: OrganizationSceneTopologyInput) {
  const selectedId = organization.id;
  const organizationProfile = TOPOLOGY_PAGE_PROFILES.organization;
  const verticalCount = organization.data.domains?.length ?? 0;
  const employeeCount = organization.data.employees ?? 0;
  const rootLabel = organization.data.shortName ?? organization.data.acronym ?? organization.data.name;
  const rootSubtitle = organization.data.region || organization.data.industry || organization.data.status || "Organization";

  const rootNode: OrganizationSceneNode = {
    id: selectedId,
    label: rootLabel,
    subtitle: rootSubtitle,
    q: 0,
    r: 0,
    variant: "root",
    size: "root",
    active: true,
    selected: true,
  };

  const servicesAnchorNode: OrganizationSceneNode = {
    id: `${selectedId}::services-anchor`,
    label: "SERVICES",
    q: -6,
    r: 0,
    variant: "anchor",
    size: "lg",
    active: false,
    selected: false,
    disabled: true,
  };

  const peopleAnchorNode: OrganizationSceneNode = {
    id: `${selectedId}::people-anchor`,
    label: "PEOPLE",
    q: 6,
    r: 0,
    variant: "anchor",
    size: "lg",
    active: false,
    selected: false,
    disabled: true,
  };

  const statAnchorNode: OrganizationSceneNode = {
    id: `${selectedId}::stats-anchor`,
    label: "STATS",
    q: 0,
    r: -5,
    variant: "anchor",
    size: "lg",
    active: false,
    selected: false,
    disabled: true,
  };

  const statNodes = placeClusterNodes(
    [
      {
        id: `${selectedId}::stat-employees`,
        label: String(employeeCount),
        subtitle: "employees",
        q: 0,
        r: 0,
        variant: "reference",
        size: "sm",
        active: false,
        selected: false,
        disabled: true,
      },
      {
        id: `${selectedId}::stat-verticals`,
        label: String(verticalCount),
        subtitle: "verticals",
        q: 0,
        r: 0,
        variant: "reference",
        size: "sm",
        active: false,
        selected: false,
        disabled: true,
      },
      {
        id: `${selectedId}::stat-industry`,
        label: organization.data.industry || "n/a",
        subtitle: "industry",
        q: 0,
        r: 0,
        variant: "reference",
        size: "sm",
        active: false,
        selected: false,
        disabled: true,
      },
    ],
    { q: 0, r: -5 },
    1,
  );

  const serviceNodes = placeClusterNodes(
    (organization.data.businessServices ?? []).slice(0, 6).map((service, index) => ({
      id: `${selectedId}::service-${index}`,
      label: service,
      subtitle: "Service",
      q: 0,
      r: 0,
      variant: "reference",
      size: "sm",
      active: false,
      selected: false,
      disabled: true,
    })),
    { q: -6, r: 0 },
    1,
  );

  const peopleNodes = placeClusterNodes(
    relatedPeople.map((person) => ({
      id: person.id,
      label: person.data.name,
      subtitle: person.data.role || person.data.department || person.data.archetype || "Employee",
      q: 0,
      r: 0,
      variant: "reference",
      size: "sm",
      active: false,
      selected: false,
    })),
    { q: 6, r: 0 },
    1,
  );

  const organizationLayout = createPresentationTopology({
    id: selectedId,
    title: rootLabel,
    subtitle: rootSubtitle,
    summary: organization.data.summary,
    status: organization.data.status ?? "ready",
    route: organization.data.href ?? `/organizations/${selectedId}`,
    role: "dossier",
    sceneLayout: organizationProfile.scene.layout,
    topologyLayout: organizationProfile.scene.topologyLayout,
    anchors: [
      {
        id: "services",
        label: "SERVICES",
        subtitle: "Tier",
        children: serviceNodes.map((node) => ({
          id: node.id,
          label: node.label,
          subtitle: node.subtitle,
        })),
      },
      {
        id: "people",
        label: "PEOPLE",
        subtitle: "Tier",
        children: peopleNodes.map((node) => ({
          id: node.id,
          label: node.label,
          subtitle: node.subtitle,
        })),
      },
      {
        id: "stats",
        label: "STATS",
        subtitle: "Tier",
        children: statNodes.map((node) => ({
          id: node.id,
          label: node.label,
          subtitle: node.subtitle,
        })),
      },
    ],
  });
  const organizationLayoutNodes = organizationLayout.nodes;
  rootNode.q = organizationLayoutNodes[0]?.q ?? rootNode.q;
  rootNode.r = organizationLayoutNodes[0]?.r ?? rootNode.r;
  servicesAnchorNode.q = organizationLayoutNodes[1]?.q ?? servicesAnchorNode.q;
  servicesAnchorNode.r = organizationLayoutNodes[1]?.r ?? servicesAnchorNode.r;
  peopleAnchorNode.q = organizationLayoutNodes[2]?.q ?? peopleAnchorNode.q;
  peopleAnchorNode.r = organizationLayoutNodes[2]?.r ?? peopleAnchorNode.r;
  statAnchorNode.q = organizationLayoutNodes[3]?.q ?? statAnchorNode.q;
  statAnchorNode.r = organizationLayoutNodes[3]?.r ?? statAnchorNode.r;

  let organizationLayoutIndex = 4;
  for (const node of serviceNodes) {
    const position = organizationLayoutNodes[organizationLayoutIndex++];
    node.q = position?.q ?? node.q;
    node.r = position?.r ?? node.r;
  }
  for (const node of peopleNodes) {
    const position = organizationLayoutNodes[organizationLayoutIndex++];
    node.q = position?.q ?? node.q;
    node.r = position?.r ?? node.r;
  }
  for (const node of statNodes) {
    const position = organizationLayoutNodes[organizationLayoutIndex++];
    node.q = position?.q ?? node.q;
    node.r = position?.r ?? node.r;
  }

  const topologyNodes: OrganizationSceneNode[] = [
    rootNode,
    servicesAnchorNode,
    peopleAnchorNode,
    statAnchorNode,
    ...statNodes,
    ...serviceNodes,
    ...peopleNodes,
  ];

  const topologyEdges: OrganizationSceneEdge[] = [
    {
      from: rootNode.id,
      to: servicesAnchorNode.id,
      kind: "contains",
      active: false,
      muted: true,
    },
    {
      from: rootNode.id,
      to: peopleAnchorNode.id,
      kind: "contains",
      active: false,
      muted: true,
    },
    {
      from: rootNode.id,
      to: statAnchorNode.id,
      kind: "contains",
      active: false,
      muted: true,
    },
    ...statNodes.map((node) => ({
      from: statAnchorNode.id,
      to: node.id,
      kind: "contains",
      active: false,
      muted: true,
    })),
    ...serviceNodes.map((node) => ({
      from: servicesAnchorNode.id,
      to: node.id,
      kind: "contains",
      active: false,
      muted: true,
    })),
    ...peopleNodes.map((node) => ({
      from: peopleAnchorNode.id,
      to: node.id,
      kind: "contains",
      active: false,
      muted: true,
    })),
  ];

  return {
    rootNode,
    servicesAnchorNode,
    peopleAnchorNode,
    statAnchorNode,
    statNodes,
    serviceNodes,
    peopleNodes,
    topologyNodes,
    topologyEdges,
  };
}
